import argparse
import time

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field

from app.config import cursor_ttl_seconds
from app.rules import cursor as cursors
from app.rules import order_rules
from app.store import imports, orders
from app.store.db import connect, migrate

app = FastAPI(title="settlement-ledger")

ORDER_STATUSES = ("accepted", "settled")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class RefundIn(BaseModel):
    refund_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

class ImportIn(BaseModel):
    tenant: str = Field(min_length=1)
    batch_id: str = Field(min_length=1)
    # 行内容逐行校验、部分成功，这里不做整批预校验。
    rows: list[dict] = Field(default_factory=list)

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.post("/orders/import", status_code=202)
def import_orders(body: ImportIn) -> dict:
    try:
        return imports.submit(body.tenant, body.batch_id, body.rows)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))

@app.get("/orders/import/{batch_id}")
def import_status(batch_id: str, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    batch = imports.get_batch(x_tenant, batch_id)
    if batch is None:
        raise HTTPException(status_code=404, detail="batch not found")
    return batch

@app.get("/orders")
def search_orders(
    order_id_prefix: str | None = None,
    status: str | None = None,
    min_paid_cents: int | None = None,
    page_size: int = 50,
    cursor: str | None = None,
    x_tenant: str = Header(default=""),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    if status is not None and status not in ORDER_STATUSES:
        raise HTTPException(status_code=400, detail="unsupported status")
    if min_paid_cents is not None and min_paid_cents < 0:
        raise HTTPException(status_code=400, detail="min_paid_cents must be non-negative")
    filters = {"order_id_prefix": order_id_prefix, "status": status, "min_paid_cents": min_paid_cents}
    after = None
    if cursor is not None:
        # 游标只在同租户、同过滤条件且未过期时有效，各类失败原因可区分。
        try:
            data = cursors.decode(cursor)
        except cursors.CursorError as error:
            raise HTTPException(status_code=400, detail=error.reason)
        if data["tenant"] != x_tenant:
            raise HTTPException(status_code=400, detail="cursor_tenant_mismatch")
        if time.time() - float(data["iat"]) > cursor_ttl_seconds():
            raise HTTPException(status_code=400, detail="cursor_expired")
        if data["filters"] != filters:
            raise HTTPException(status_code=400, detail="cursor_filter_mismatch")
        after = data["last"]
    page, has_more = orders.search(x_tenant, order_id_prefix, status, min_paid_cents, page_size, after)
    next_cursor = None
    if has_more and page:
        next_cursor = cursors.encode(
            {"v": 1, "tenant": x_tenant, "filters": filters, "last": page[-1]["order_id"], "iat": time.time()}
        )
    return {"tenant": x_tenant, "orders": page, "next_cursor": next_cursor}

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        order = orders.add_payment(x_tenant, order_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/refunds")
def add_refund(order_id: str, body: RefundIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        result = orders.add_refund(x_tenant, order_id, body.refund_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if result is None:
        raise HTTPException(status_code=404, detail="order not found")
    return result

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    imports.resume_incomplete()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

import sqlite3
from pathlib import Path

from app.config import db_path

MIGRATIONS_DIR = Path(__file__).resolve().parents[2] / "migrations"
MIGRATIONS = ("001_init.sql", "002_refunds.sql", "003_imports.sql")

def connect() -> sqlite3.Connection:
    path = db_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(path, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn

def migrate() -> None:
    conn = connect()
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS schema_migrations(name TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (datetime('now')))"
        )
        applied = {row["name"] for row in conn.execute("SELECT name FROM schema_migrations")}
        for name in MIGRATIONS:
            if name in applied:
                continue
            sql = (MIGRATIONS_DIR / name).read_text(encoding="utf-8")
            conn.execute("BEGIN")
            try:
                # 002 含 ALTER TABLE ADD COLUMN，老库重复执行会报错；
                # 按语句逐条执行并容忍“列已存在/表已存在”，保证升级可重入。
                for stmt in (s.strip() for s in sql.split(";") if s.strip()):
                    try:
                        conn.execute(stmt)
                    except sqlite3.OperationalError as error:
                        message = str(error)
                        if "duplicate column name" not in message and "already exists" not in message:
                            raise
                conn.execute("INSERT OR IGNORE INTO schema_migrations(name) VALUES(?)", (name,))
                conn.execute("COMMIT")
            except Exception:
                conn.execute("ROLLBACK")
                raise
    finally:
        conn.close()

import hashlib
import json
import sqlite3
import threading

from app.rules.order_rules import ALLOWED_CURRENCIES
from app.store.db import connect

# 每个批次最多一个后台工作线程；重复提交或重启续跑都通过 _ensure_worker 汇入同一线程。
_workers: dict[tuple[str, str], threading.Thread] = {}
_workers_lock = threading.Lock()

def hash_rows(rows: list) -> str:
    canonical = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

def _validate_row(raw) -> tuple[str | None, int | None, str | None, str | None]:
    # 逐行校验，规则与单笔受理一致：标识非空、金额为正整数、币种在允许集合内。
    if not isinstance(raw, dict):
        return None, None, None, "row must be an object"
    order_id = raw.get("order_id")
    if not isinstance(order_id, str) or not order_id:
        return None, None, None, "order_id is required"
    amount = raw.get("amount_cents")
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        return None, None, None, "amount_cents must be a positive integer"
    currency = raw.get("currency")
    if not isinstance(currency, str) or currency not in ALLOWED_CURRENCIES:
        return None, None, None, "unsupported currency"
    return order_id, amount, currency, None

def submit(tenant: str, batch_id: str, rows: list) -> dict:
    # 幂等受理：同（租户, 批次标识）同内容直接返回与首次一致的回执；
    # 同标识不同内容按冲突拒绝。批次与行原文落库后才启动处理，提交不丢。
    digest = hash_rows(rows)
    payload = json.dumps(rows, ensure_ascii=False)
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT request_hash FROM import_batches WHERE tenant=? AND batch_id=?",
            (tenant, batch_id),
        ).fetchone()
        if existing is None:
            conn.execute(
                "INSERT INTO import_batches(tenant, batch_id, total_rows, status, request_hash, payload) VALUES(?,?,?,'processing',?,?)",
                (tenant, batch_id, len(rows), digest, payload),
            )
        conn.execute("COMMIT")
    finally:
        conn.close()
    if existing is not None and existing["request_hash"] != digest:
        raise ValueError("batch_id already used with different rows")
    _ensure_worker(tenant, batch_id)
    return {"tenant": tenant, "batch_id": batch_id, "status": "accepted", "total_rows": len(rows)}

def get_batch(tenant: str, batch_id: str) -> dict | None:
    conn = connect()
    try:
        batch = conn.execute(
            "SELECT tenant, batch_id, total_rows, status FROM import_batches WHERE tenant=? AND batch_id=?",
            (tenant, batch_id),
        ).fetchone()
        if batch is None:
            return None
        # 计数由逐行结果实时汇总，天然闭合：成功 + 失败 = 已处理行数。
        counts = {
            row["outcome"]: row["n"]
            for row in conn.execute(
                "SELECT outcome, COUNT(*) AS n FROM import_rows WHERE tenant=? AND batch_id=? GROUP BY outcome",
                (tenant, batch_id),
            )
        }
        failures = conn.execute(
            "SELECT row_no, order_id, error FROM import_rows WHERE tenant=? AND batch_id=? AND outcome='failed' ORDER BY row_no",
            (tenant, batch_id),
        ).fetchall()
    finally:
        conn.close()
    success = counts.get("success", 0)
    failure = counts.get("failed", 0)
    return {
        "tenant": batch["tenant"],
        "batch_id": batch["batch_id"],
        "status": batch["status"],
        "total_rows": batch["total_rows"],
        "processed_rows": success + failure,
        "success_count": success,
        "failure_count": failure,
        "failures": [
            {"row_no": row["row_no"], "order_id": row["order_id"], "error": row["error"]}
            for row in failures
        ],
    }

def resume_incomplete() -> None:
    # 服务重启后扫出未完成的批次继续处理；已落库的行会被跳过，不重复受理。
    conn = connect()
    try:
        pending = conn.execute(
            "SELECT tenant, batch_id FROM import_batches WHERE status='processing'"
        ).fetchall()
    finally:
        conn.close()
    for row in pending:
        _ensure_worker(row["tenant"], row["batch_id"])

def _ensure_worker(tenant: str, batch_id: str) -> None:
    key = (tenant, batch_id)
    with _workers_lock:
        thread = _workers.get(key)
        if thread is not None and thread.is_alive():
            return
        thread = threading.Thread(target=_run, args=(tenant, batch_id), daemon=True)
        _workers[key] = thread
        thread.start()

def _run(tenant: str, batch_id: str) -> None:
    conn = connect()
    try:
        batch = conn.execute(
            "SELECT payload FROM import_batches WHERE tenant=? AND batch_id=?",
            (tenant, batch_id),
        ).fetchone()
    finally:
        conn.close()
    if batch is None:
        return
    rows = json.loads(batch["payload"])
    for index, raw in enumerate(rows):
        _process_row(tenant, batch_id, index + 1, raw)
    conn = connect()
    try:
        conn.execute(
            "UPDATE import_batches SET status='completed' WHERE tenant=? AND batch_id=?",
            (tenant, batch_id),
        )
    finally:
        conn.close()

def _process_row(tenant: str, batch_id: str, row_no: int, raw) -> None:
    order_id, amount, currency, error = _validate_row(raw)
    # 校验失败的行也尽量保留原始订单标识，便于逐行定位。
    if order_id is None and isinstance(raw, dict) and isinstance(raw.get("order_id"), str):
        order_id = raw["order_id"]
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        done = conn.execute(
            "SELECT 1 FROM import_rows WHERE tenant=? AND batch_id=? AND row_no=?",
            (tenant, batch_id, row_no),
        ).fetchone()
        if done is not None:
            # 中断续跑：该行此前已原子落库，直接跳过。
            conn.execute("ROLLBACK")
            return
        if error is None:
            try:
                conn.execute(
                    "INSERT INTO orders(tenant, order_id, amount_cents, paid_cents, currency, status) VALUES(?,?,?,0,?,'accepted')",
                    (tenant, order_id, amount, currency),
                )
                outcome, reason = "success", None
            except sqlite3.IntegrityError:
                # 与库内已有订单重复：只拒绝该行，不改动既有订单。
                outcome, reason = "failed", "order already accepted"
        else:
            outcome, reason = "failed", error
        conn.execute(
            "INSERT INTO import_rows(tenant, batch_id, row_no, order_id, outcome, error) VALUES(?,?,?,?,?,?)",
            (tenant, batch_id, row_no, order_id, outcome, reason),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()

import os
from pathlib import Path


def db_path() -> Path:
    return Path(os.environ.get("APP_DB", "var/app.sqlite"))

def tenant_header() -> str:
    return os.environ.get("APP_TENANT_HEADER", "X-Tenant")

def cursor_secret() -> str:
    return os.environ.get("APP_CURSOR_SECRET", "settlement-ledger-dev-secret")

def cursor_ttl_seconds() -> int:
    return int(os.environ.get("APP_CURSOR_TTL", "3600"))

ALLOWED_CURRENCIES = {"CNY", "USD", "EUR", "JPY"}

def assert_currency(currency: str) -> None:
    if currency not in ALLOWED_CURRENCIES:
        raise ValueError("unsupported currency")

